presets.css:
/* ===== 由「气泡生成器」导出 · 贴到对话主题 A 区 ===== */
.chat-thread {
  /* 顶栏胶囊 */
  --dress-header-bg: rgba(255, 194, 200, 0.290);
  --dress-header-blur: 16px;
  --dress-header-border: rgba(0, 0, 0, 0.120);
  --dress-header-radius: 23px;
  --dress-header-shadow: none;
  --dress-header-title-color: #1a1a1a;
  --dress-header-title-size: 15px;
  --dress-header-title-weight: 500;
  --dress-header-icon-color: #1a1a1a;

  /* 我方气泡 */
  --dress-bubble-me-bg-gradient: linear-gradient(67deg, #ffcfe1, #ffffff);
  --dress-bubble-me-bg: #ffcfe1;
  --dress-bubble-me-fg: #1a1a1a;
  --dress-bubble-me-border: none;
  --dress-bubble-me-shadow: 0 2px 11px rgba(0, 0, 255, 0.077);
  --dress-bubble-me-radius: 11px;

  /* 对方气泡 */
  --dress-bubble-them-bg-gradient: linear-gradient(76deg, #fff7f7, #e9d3ed);
  --dress-bubble-them-bg: #fff7f7;
  --dress-bubble-them-fg: #1a1a1a;
  --dress-bubble-them-border: none;
  --dress-bubble-them-shadow: 0 2px 7px rgba(0, 0, 0, 0.050);
  --dress-bubble-them-radius: 6px;

  /* 输入胶囊 */
  --dress-compose-bar-bg: rgba(255, 255, 255, 0.150);
  --dress-compose-bar-fg: #1a1a1a;
  --dress-compose-bar-radius: 3px;
  --dress-compose-bar-border: 1px solid rgba(0, 0, 0, 0.060);
  --dress-compose-bar-shadow: none;
  --dress-compose-bar-blur: blur(0px);

  /* 其他 */
  --dress-timestamp-color: #000000;
}
